local JazzNativeWeaponSelector=(function()
-- Pure resolver for native photographed layers. No globals or engine mutation.
local M = {}
local function matches(when, values)
  local count=0
  for slot,id in pairs(when or {}) do
    if values[slot]~=id then return false,0 end
    count=count+1
  end
  return true,count
end
function M.resolve(registry,item)
  local profile=item and registry.weapons[item.class]
  if not profile then return nil,"unsupported-weapon" end
  local values,parts={},{}
  for _,slot in ipairs(profile.slots) do
    local value=item.components and item.components[slot.slot]
    if value==nil then value=slot.default end
    if value==false then value="" end
    if not slot.options[value] then return nil,"unknown-component:"..tostring(slot.slot) end
    values[slot.slot]=value
  end
  local rail_slots={Dovetail=true,Rail=true,RailSide=true,Conversion=true}
  for slot,value in pairs(item.components or {}) do
    if values[slot]==nil and value and value~="" and not rail_slots[slot] then return nil,"unknown-slot:"..slot end
  end
  for spot,entity in pairs(profile.base) do parts[spot]=entity end
  for _,slot in ipairs(profile.slots) do
    local rule=profile.rules[slot.slot] and profile.rules[slot.slot][values[slot.slot]]
    if not rule then return nil,"missing-component-rule:"..tostring(slot.slot) end
    for spot,entity in pairs(rule) do parts[spot]=entity or nil end
  end
  for _,override in ipairs(profile.overrides or {}) do
    if matches(override.when,values) then
      for spot,entity in pairs(override.parts) do parts[spot]=entity or nil end
    end
  end
  local host=item.Entity or parts.__host
  parts.__host=host
  local art=profile.art[host]
  if not art then return nil,"unknown-host" end
  local chosen,visiting={},{}
  local function choose(spot)
    if chosen[spot] then return chosen[spot] end
    if visiting[spot] then return nil end
    visiting[spot]=true
    local candidates=art[spot] and art[spot][parts[spot]]
    local best,best_score=nil,-1
    for _,candidate in ipairs(candidates or {}) do
      local ok,score=matches(candidate.when,values)
      if ok and candidate.parent then
        ok=parts[candidate.parent]~=nil and choose(candidate.parent)==candidate.parent_id
      end
      if ok and score>best_score then best,best_score=candidate.id,score end
    end
    visiting[spot]=nil
    chosen[spot]=best
    return best
  end
  local layers,nodes,seen={},{},{}
  local bounds={math.huge,math.huge,-math.huge,-math.huge}
  for spot in pairs(parts) do
    local id=choose(spot)
    local layer=id and registry.layers[id]
    if not layer then return nil,"missing-art:"..spot end
    if not seen[id] then
      seen[id]=true;nodes[#nodes+1]=id
      if layer.image and layer.bounds then
        layers[#layers+1]={id=id,image=layer.image,z=layer.z,bounds=layer.bounds}
        for i=1,2 do bounds[i]=math.min(bounds[i],layer.bounds[i]) end
        for i=3,4 do bounds[i]=math.max(bounds[i],layer.bounds[i]) end
      end
    end
  end
  table.sort(layers,function(a,b) return a.z==b.z and a.id<b.id or a.z<b.z end)
  if #layers==0 then return nil,"empty-assembly" end
  table.sort(nodes)
  local key={registry.revision,item.class,host}
  for _,layer in ipairs(layers) do key[#key+1]=layer.id end
  return {layers=layers,nodes=nodes,key=table.concat(key,"|"),bounds=bounds,width=profile.width,height=profile.height}
end
return M

end)()
local JazzNativeWeaponBinder=(function()
-- Native XImage adapter. A window owns its layers; items and saves stay untouched.
local M = {}
local states=setmetatable({}, {__mode="k"})
local transparent=RGBA(255,255,255,0)
-- ReloadLua replaces the weak table while existing inventory windows survive.
-- Recover their original tint from the color pass before replacing old groups.
local function recover(img)
  if states[img] then return end
  local color,disabled_color
  for i=#img,1,-1 do
    local group=img[i]
    if group.Id=="idJazzNativeWeaponLayers" then
      local last=group[#group]
      if last and last.ImageColor~=transparent then color=last.ImageColor end
      if last and last.DisabledImageColor~=transparent then disabled_color=last.DisabledImageColor end
      group:delete()
    end
  end
  if img.ImageColor==transparent and color then img:SetImageColor(color) end
  if img.DisabledImageColor==transparent and disabled_color then img:SetDisabledImageColor(disabled_color) end
end
function M.clear(img)
  recover(img)
  local state=states[img]
  if not state then return end
  if state.group and state.group.window_state~="destroying" then state.group:delete() end
  if img.ImageColor==transparent then img:SetImageColor(state.color) end
  if img.DisabledImageColor==transparent then img:SetDisabledImageColor(state.disabled_color) end
  states[img]=nil
end
function M.crop(plan)
  local b=plan.bounds;local width,height=plan.width,plan.height
  local padding=width==162 and 5 or 8
  local crop_width=math.max((b[3]-b[1]+4)*width/(width-2*padding),(b[4]-b[2]+4)*height/(height-2*padding)*width/height)
  local crop_height=crop_width*height/width
  local cx,cy=(b[1]+b[3])/2,(b[2]+b[4])/2
  return {math.floor(cx-crop_width/2),math.floor(cy-crop_height/2),math.ceil(cx+crop_width/2),math.ceil(cy+crop_height/2)}
end
function M.bind(img,item,registry,selector)
  if not img or img.window_state=="destroying" then return false end
  recover(img)
  local plan=selector.resolve(registry,item)
  if not plan then M.clear(img);return false end
  for _,layer in ipairs(plan.layers) do
    UIL.RequestImage(layer.image)
    local w,h=UIL.MeasureImage(layer.image)
    if not w or w<=0 or not h or h<=0 then M.clear(img);return false end
  end
  local state=states[img]
  local color=state and img.ImageColor==transparent and state.color or img.ImageColor
  local disabled_color=state and img.DisabledImageColor==transparent and state.disabled_color or img.DisabledImageColor
  local style=table.concat({tostring(img.ImageScale),tostring(img.ImageFit),tostring(color),tostring(disabled_color),tostring(img.Desaturation),tostring(img.DisabledDesaturation),tostring(img.Angle),tostring(img.FlipX),tostring(img.FlipY)},"|")
  if state and state.key==plan.key and state.style==style then return true end
  M.clear(img)
  local group=XControl:new({Id="idJazzNativeWeaponLayers",Dock="box",HandleMouse=false,Visible=false,ZOrder=1},img)
  local crop=M.crop(plan)
  local rect=box(crop[1],crop[2],crop[3],crop[4])
  local sx,sy=1000,1000
  if img.ImageScale then sx,sy=img.ImageScale:xy() end
  local scale=point(math.floor(plan.width*sx/(crop[3]-crop[1])),math.floor(plan.height*sy/(crop[4]-crop[2])))
  -- Draw all soft silhouettes before color: attached parts cover internal seams.
  for pass=1,2 do
    for _,layer in ipairs(plan.layers) do
      XImage:new({Dock="box",HandleMouse=false,Image=layer.image,
        ImageRect=rect,ImageFit=img.ImageFit,ImageScale=scale,
        ImageColor=pass==1 and RGB(3,3,3) or color,
        DisabledImageColor=pass==1 and RGBA(3,3,3,160) or disabled_color,
        Desaturation=img.Desaturation,DisabledDesaturation=img.DisabledDesaturation,
        Angle=img.Angle,FlipX=img.FlipX,FlipY=img.FlipY,
        EffectType=pass==1 and "glow" or "none",EffectPixels=pass==1 and 6 or 0,
        EffectColor=RGBA(3,3,3,230)},group)
    end
  end
  states[img]={key=plan.key,style=style,group=group,color=color,disabled_color=disabled_color}
  img:SetImageColor(transparent);img:SetDisabledImageColor(transparent)
  group:SetEnabled(img:GetEnabled())
  if img.window_state=="open" then group:Open() end
  group:SetVisible(true)
  return true
end
return M

end)()
-- END JAZZ NATIVE WEAPON LAYERS

function JazzWeaponIcon_BindItemImage(img, item)
    if not img or img.window_state=="destroying" then return false end
    if not item then JazzNativeWeaponBinder.clear(img);return false end
    local icon = JazzWeaponIcon_GetCaptured(item) or (item.GetItemUIIcon and item:GetItemUIIcon()) or item.Icon
    if icon then img:SetImage(icon) end
    return JazzNativeWeaponBinder.bind(img, item, JazzNativeWeaponRegistry, JazzNativeWeaponSelector)
end

function JazzWeaponIcon_RefreshWeaponDisplays()
	local function visit(win)
		if not win then
			return
		end
		local item = win.GetContext and win:GetContext() or rawget(win, "context")
		if item and JazzAttachChips_IsFirearm and JazzAttachChips_IsFirearm(item) then
			local icon = rawget(win, "idItemImg") or rawget(win, "idIcon")
				or (win.ResolveId and (win:ResolveId("idItemImg") or win:ResolveId("idIcon")))
			if icon then
				JazzWeaponIcon_BindItemImage(icon, item)
				if JazzAttachChips_Apply then
					JazzAttachChips_Apply(icon, item)
				end
			end
		end
		if win.ForEachChild then
			win:ForEachChild(visit)
		else
			for _, child in ipairs(win) do
				visit(child)
			end
		end
	end
	local roots = {}
	local igi = GetInGameInterface and GetInGameInterface()
	if igi then
		roots[#roots + 1] = igi
	end
	local mode = GetInGameInterfaceModeDlg and GetInGameInterfaceModeDlg()
	if mode and mode ~= igi then
		roots[#roots + 1] = mode
	end
	local inv = GetMercInventoryDlg and GetMercInventoryDlg()
	if inv then
		roots[#roots + 1] = inv
	end
	for _, root in ipairs(roots) do
		visit(root)
	end
end

